// Regenerates src/country-data.ts from world-countries + libphonenumber-js.
// world-countries is a devDependency used only here, so the published package
// ships this small generated file instead of the ~600 kB dataset.
//
// Run with: node scripts/generate-country-data.mjs
import worldCountries from 'world-countries'
import { getCountries, getCountryCallingCode } from 'libphonenumber-js'
import { writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'

const worldCountryMap = new Map(worldCountries.map((c) => [c.cca2, c]))

// Territories libphonenumber supports that world-countries lacks complete metadata for.
const FALLBACK_COUNTRIES = {
  AC: { name: 'Ascension Island', dialCode: '+247' },
  TA: { name: 'Tristan da Cunha', dialCode: '+290' },
  BQ: { name: 'Caribbean Netherlands', dialCode: '+599' },
}

function normalizeDialCode(root, suffix) {
  const normalizedRoot = root.startsWith('+') ? root : `+${root}`
  const digitsOnlySuffix = suffix.replace(/\D/g, '')
  return `${normalizedRoot}${digitsOnlySuffix}`
}

function buildDialCodes(country, fallbackDialCode) {
  const root = country?.idd?.root
  if (!root) {
    return [fallbackDialCode]
  }
  const suffixes = country.idd?.suffixes?.length ? country.idd.suffixes : ['']
  const dialCodes = suffixes
    .map((suffix) => normalizeDialCode(root, suffix))
    .filter((dialCode) => /^\+\d+$/.test(dialCode))
  return Array.from(new Set([fallbackDialCode, ...(dialCodes.length ? dialCodes : [])]))
}

const data = {}
for (const code of getCountries()) {
  const country = worldCountryMap.get(code)
  const fallback = FALLBACK_COUNTRIES[code]
  const dialCode = fallback?.dialCode ?? `+${getCountryCallingCode(code)}`
  data[code] = {
    name: country?.name.common ?? fallback?.name ?? code,
    dialCodes: buildDialCodes(country, dialCode),
  }
}
// Include fallback-only territories not returned by getCountries().
for (const [code, fallback] of Object.entries(FALLBACK_COUNTRIES)) {
  if (!data[code]) {
    data[code] = { name: fallback.name, dialCodes: [fallback.dialCode] }
  }
}

const banner = `// GENERATED by scripts/generate-country-data.mjs. Do not edit by hand.
// Country names and dial codes, extracted so the package does not ship the
// full world-countries dataset. Regenerate when the libphonenumber region set
// or world-countries metadata changes.
`
const body = `export interface CountryDatum {
  name: string
  dialCodes: string[]
}

export const COUNTRY_DATA: Record<string, CountryDatum> = ${JSON.stringify(data, null, 2)}
`
const out = join(dirname(fileURLToPath(import.meta.url)), '..', 'src', 'country-data.ts')
writeFileSync(out, banner + '\n' + body)
console.log('wrote', out, '|', Object.keys(data).length, 'countries')
